html, body {
    font-size: 10px !important;
    margin: 0 !important;
    padding: 0 !important;
}

@page {
    size: A4 portrait;
    margin: 8mm 8mm 8mm 8mm;
}

/* ── Container ── */
.ctc-print-container {
    border: 2px solid #000;
    padding: 8px;
    font-family: Arial, sans-serif;
    font-size: 10px;
    width: 100%;
    box-sizing: border-box;
}

/* ── Header ── */
.ctc-print-header {
    text-align: center;
    border-bottom: 2px solid #000;
    padding-bottom: 4px;
    margin-bottom: 6px;
}
.ctc-print-header h2 {
    margin: 0 0 2px 0;
    font-size: 13px;
    font-weight: bold;
    color: #000;
}
.ctc-print-subtitle {
    margin: 0;
    font-size: 10px;
    color: #444;
    font-style: italic;
}

/* ── Section title ── */
.ctc-section-title {
    background-color: #e8e8e8;
    font-weight: bold;
    font-size: 10px;
    padding: 3px 5px;
    border: 1px solid #000;
    margin-bottom: 0;
    color: #000;
}

/* ── Employee info table ── */
.ctc-info-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 10px;
    table-layout: fixed;
    margin-bottom: 6px;
    border: 1px solid #000;
    border-top: none;
}
.ctc-info-table tbody tr:nth-child(even) { background-color: #f9f9f9; }
.ctc-info-table tbody tr:nth-child(odd)  { background-color: #fff; }
.ctc-info-table .lbl {
    font-weight: 600;
    padding: 2px 5px;
    color: #000;
    font-size: 10px;
    width: 22%;
    border-right: 1px solid #ddd;
}
.ctc-info-table .val {
    padding: 2px 5px;
    color: #333;
    font-size: 10px;
    width: 28%;
    border-right: 1px solid #eee;
}

/* ── KPI summary table ── */
.ctc-kpi-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 10px;
    margin-bottom: 6px;
    border: 1px solid #000;
    border-top: none;
}
.ctc-kpi-table .kpi-cell {
    padding: 5px 6px;
    text-align: center;
    border-right: 1px solid #000;
    background: #fff;
    width: 20%;
}
.ctc-kpi-table .kpi-cell:last-child { border-right: none; }
.ctc-kpi-table .kpi-net { background: #d1fae5; }
.kpi-lbl {
    font-size: 8px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: #555;
    margin-bottom: 2px;
}
.kpi-val {
    font-size: 11px;
    font-weight: 700;
    color: #000;
}

/* ── Breakdown table ── */
.ctc-breakdown-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 10px;
    margin-bottom: 0;
    table-layout: fixed;
    border: 1px solid #000;
    border-top: none;
}
.col-header {
    padding: 4px;
    border: 1px solid #000;
    font-size: 10px;
    font-weight: bold;
    text-align: center;
    color: #000;
}
.col-header-earn { background-color: #d1fae5; }
.col-header-ded  { background-color: #fee2e2; }
.col-header-emp  { background-color: #dbeafe; }

.sub-header {
    background-color: #f3f4f6;
    padding: 2px 5px;
    border: 1px solid #000;
    font-size: 9px;
    font-weight: 600;
    color: #000;
}
.sub-left  { text-align: left; }
.sub-right { text-align: right; }

.ctc-breakdown-table tbody tr.row-even { background-color: #fff; }
.ctc-breakdown-table tbody tr.row-odd  { background-color: #f9f9f9; }

.data-label {
    padding: 2px 5px;
    border: 1px solid #ddd;
    font-size: 10px;
    color: #000;
    word-wrap: break-word;
}
.data-value {
    padding: 2px 5px;
    border: 1px solid #ddd;
    font-size: 10px;
    text-align: right;
    color: #000;
    white-space: nowrap;
}

/* Tags inside cells */
.tag-var  { display:inline-block; padding:0 3px; border-radius:3px; font-size:8px; font-weight:700; background:#fff9db; color:#864e00; margin-left:3px; }
.tag-oth  { display:inline-block; padding:0 3px; border-radius:3px; font-size:8px; font-weight:700; background:#f3f0ff; color:#6741d9; margin-left:3px; }
.tag-excl { display:inline-block; padding:0 3px; border-radius:3px; font-size:8px; font-weight:700; background:#fff5f5; color:#c92a2a; margin-left:3px; }

/* Total footer row */
.ctc-breakdown-table tfoot .total-row {
    background-color: #e8e8e8;
    font-weight: bold;
}
.total-lbl {
    padding: 3px 5px;
    border: 1px solid #000;
    font-size: 10px;
    font-weight: bold;
    color: #000;
}
.total-val {
    padding: 3px 5px;
    border: 1px solid #000;
    font-size: 10px;
    font-weight: bold;
    text-align: right;
    color: #000;
    white-space: nowrap;
}

/* ── Net salary ── */
.ctc-net-section {
    background-color: #d1fae5;
    border: 2px solid #000;
    border-top: none;
    padding: 5px 8px;
    display: flex;
    justify-content: space-between;
    align-items: center;
}
.net-label {
    font-size: 11px;
    font-weight: bold;
    color: #000;
}
.net-value {
    font-size: 12px;
    font-weight: bold;
    color: #000;
}
.ctc-net-words {
    background-color: #f0fdf4;
    border: 1px solid #000;
    border-top: none;
    padding: 3px 8px;
    font-size: 9px;
    color: #000;
    font-style: italic;
    text-align: center;
    margin-bottom: 0;
}

/* ── Loader (screen only) ── */
#ctc-loader { display: none; }
#ctc-loader.active { display: flex; }

/* ── Print overrides ── */
@media print {
    html, body {
        margin: 0 !important;
        padding: 0 !important;
        font-size: 10px !important;
    }
    .ctc-print-container {
        border: 2px solid #000;
        padding: 8px;
        page-break-inside: avoid;
    }
    #ctc-loader { display: none !important; }
    .tag-var, .tag-oth, .tag-excl {
        -webkit-print-color-adjust: exact;
        print-color-adjust: exact;
    }
    .col-header-earn, .col-header-ded, .col-header-emp,
    .ctc-net-section, .ctc-kpi-table .kpi-net {
        -webkit-print-color-adjust: exact;
        print-color-adjust: exact;
    }
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    margin: 0 !important;
    padding: 0 !important;
}

.print-format-gutter,
.print-format.print-format-preview,
.page-container,
.page-content {
    padding: 0 !important;
    margin: 0 !important;
}

.print-format {
    font-family: Arial, Helvetica, sans-serif;
    color: #000;
    width: 100% !important;
    margin: 0 !important;
    padding: 15mm !important;
    background: #fff;
    line-height: 1.3;
}

.header-section {
    text-align: center;
    margin-bottom: 20px;
}

.company-name {
    font-size: 22px;
    font-weight: 700;
    letter-spacing: 1.2px;
    margin-bottom: 10px;
}

.document-title {
    font-size: 16px;
    font-weight: 600;
    color: #333;
}

.period {
    font-size: 13px;
    color: #666;
    margin-top: 5px;
}

.table-section {
    margin-bottom: 40px;
}

.variable-pay-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 13px;
    border: 1px solid #000; /* Outer table border */
}

.variable-pay-table th,
.variable-pay-table td {
    border: 1px solid #000;  /* Borders for all rows and columns */
    padding: 12px 15px;
}

.variable-pay-table thead th {
    background: #f5f5f5;
    font-weight: 700;
    font-size: 12px;
}

.variable-pay-table tfoot td {
    background: #f5f5f5;
    font-weight: 700;
}

.bold {
    font-weight: 700;
}

.text-left {
    text-align: left;
}

.text-center {
    text-align: center;
}

.text-right {
    text-align: right;
}

.signature-section {
    display: flex;
    justify-content: center;
    margin-top: 50px;
    margin-bottom: 25px;
}

.signature-box {
    width: 35%;
    text-align: center;
}

.signature-line {
    border-top: 1.5px solid #000;
    margin-bottom: 8px;
}

.signature-label {
    font-size: 11px;
    color: #666;
}

.print-footer {
    text-align: center;
    margin-top: 30px;
    padding-top: 12px;
    border-top: 1px solid #ccc;
}

.print-footer p {
    font-size: 10px;
    color: #999;
}

@media print {
    @page {
        size: A4;
        margin: 8mm;
    }

    .print-format {
        padding: 8mm !important;
    }

    .variable-pay-table thead th,
    .variable-pay-table tfoot td {
        background: #f5f5f5 !important;
        -webkit-print-color-adjust: exact;
        print-color-adjust: exact;
    }
}

@media screen and (max-width: 768px) {
    .print-format {
        padding: 10mm !important;
    }

    .company-name {
        font-size: 18px;
    }

    .document-title {
        font-size: 14px;
    }

    .signature-box {
        width: 70%;
    }
}

