.earnings-table .data-value {
    padding: 1px 4px;
    border: 1px solid #000;
    font-size: 9px;
    line-height: 1.1;
    text-align: right;
    color: #000;
    white-space: nowrap;
}

.earnings-table tfoot .total-row {
    background-color: #e8e8e8;
    font-weight: bold;
