.earnings-table .total-value-cell {
    padding: 2px 4px;
    border: 1px solid #000;
    font-size: 9px;
    font-weight: bold;
    text-align: right;
    color: #000;
    white-space: nowrap;
}

.earnings-table .group-label-row {
    background-color: #f3f4f6;
    padding: 1px 4px;
    border: 1px solid #000;
    font-size: 7px;
    font-weight: bold;
    font-style: italic;
    text-align: left;
    color: #374151;
    text-transform: uppercase;
    letter-spacing: 0.03em;
}

.net-payable-section {
    background-color: #d1fae5;
    padding: 4px;
    text-align: center;
    border: 2px solid #000;
    margin-top: 0;
}

.net-amount {
    font-weight: bold;
    font-size: 10px;
    margin: 0 0 2px 0;
    color: #000;
}

.net-words {
    font-size: 9px;
    margin: 0;
    color: #000;
}

#payslip-loader {
    display: none;
    position: fixed;
    inset: 0;
    background: rgba(255, 255, 255, 0.88);
    z-index: 99999;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    font-family: Arial, sans-serif;
}

#payslip-loader.active { display: flex; }

.pl-spinner {
    width: 52px;
    height: 52px;
    border: 5px solid #e0e0e0;
    border-top-color: #2563eb;
    border-radius: 50%;
    animation: pl-spin 0.75s linear infinite;
    margin-bottom: 16px;
}

.pl-text {
    font-size: 14px;
    font-weight: 600;
    color: #374151;
    letter-spacing: 0.02em;
}

.pl-sub {
    font-size: 11px;
    color: #9ca3af;
    margin-top: 4px;
}

@keyframes pl-spin { to { transform: rotate(360deg); } }

